const exportData = $input.first().json;
const files = exportData.files || [];
const results = [];

// 1. Adicionar cada Nota Fiscal / Arquivo PDF ou XML individual
for (const f of files) {
  const mimeType = f.filename.endsWith('.pdf') ? 'application/pdf' :
                   (f.filename.endsWith('.xml') ? 'application/xml' :
                   (f.filename.endsWith('.png') ? 'image/png' :
                   (f.filename.endsWith('.jpg') || f.filename.endsWith('.jpeg') ? 'image/jpeg' : 'application/octet-stream')));

  results.push({
    json: {
      fileName: f.filename,
      sizeBytes: f.sizeBytes,
      tipo: 'Nota Fiscal / Documento'
    },
    binary: {
      data: {
        data: f.contentBase64,
        mimeType: mimeType,
        fileName: f.filename
      }
    }
  });
}

// 2. Adicionar o arquivo consolidado de Dados das Vendas (.json)
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const dateStr = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
const dbFileName = `dados_completos_vendas_${dateStr}.json`;
const contentStr = JSON.stringify(exportData.database || {}, null, 2);
const dbBinary = Buffer.from(contentStr, 'utf8').toString('base64');

results.push({
  json: {
    fileName: dbFileName,
    tipo: 'Banco de Dados'
  },
  binary: {
    data: {
      data: dbBinary,
      mimeType: 'application/json',
      fileName: dbFileName,
      fileExtension: 'json'
    }
  }
});

return results;
